   350  static ssize_t
   351  cdf_read(const cdf_info_t *info, off_t off, void *buf, size_t len)
   352  {
   353          size_t siz = CAST(size_t, off + len);
   354
   355          if (CAST(off_t, off + len) != CAST(off_t, siz))
   356                  goto out;
   357
   358          if (info->i_buf != NULL && info->i_len >= siz) {
   359                  (void)memcpy(buf, &info->i_buf[off], len);
   360                  return CAST(ssize_t, len);
   361          }
   362
   363          if (info->i_fd == -1)
   364                  goto out;
   365
   366          if (pread(info->i_fd, buf, len, off) != CAST(ssize_t, len))
   367                  return -1;
   368
   369          return CAST(ssize_t, len);
   370  out:
   371          errno = EINVAL;
   372          return -1;
   373  }
